def favorite_boost(event, profile):
    """Return the capped bonus for independently matching favorite kinds (SPEC section 12.4).

    :param event: candidate Event
    :param profile: UserProfile with series, club and bundle favorites
    :return: bonus between zero and MAX_FAVORITE_BOOST
    """
    return min(config.MAX_FAVORITE_BOOST,
               config.FAVORITE_BOOST * len(profile.favorite_kinds(event)))


def heuristic_score(event, profile, friends_going=0):
    """Score a candidate with M3's explicit baseline formula, capped at one.

    :param event: candidate Event
    :param profile: current user's focus and favorites
    :param friends_going: nonnegative integer count, zero before social features are available
    :return: baseline match score; this is not a trained model probability
    """
    if type(friends_going) is not int or friends_going < 0:
        raise ValueError('Friends going must be a nonnegative integer.')
    score = config.HEURISTIC_BASE_SCORE + favorite_boost(event, profile)
    if profile.wants_direction(event):
        score += config.HEURISTIC_DIRECTION_BOOST
    score += min(config.HEURISTIC_MAX_FRIEND_BOOST,
                 config.HEURISTIC_FRIEND_BOOST * friends_going)
    return min(1.0, score)


def _reasons(event, profile, friends_going, earlier_avg=None):
    """Explain at most three contributions using the same focus and favorite definitions."""
    reasons = [config.FAVORITE_REASONS[kind] for kind in profile.favorite_kinds(event)]
    if profile.wants_direction(event):
        reasons.append('Matches your focus: ' + config.DIRECTION_LABELS[event.direction_key])
    if friends_going:
        reasons.append(f'{friends_going} friends going')
    if earlier_avg is not None and earlier_avg >= config.LABEL_MIN_STARS:
        reasons.append(f'You liked {event.bundle_name} before')
    return reasons[:config.SUGGESTION_REASON_LIMIT]


class Recommender:
    """Rank with a fitted Random Forest, or the specified baseline when training is insufficient."""

    def __init__(self, model=None, feature_columns=None):
        """Accept a fitted binary forest and its training columns, or an explicit None fallback."""
        if model is not None and not isinstance(model, RandomForestClassifier):
            raise ValueError('Supply a trained Random Forest or None for baseline scoring.')
        self.model = model
        self.feature_columns = list(feature_columns) if feature_columns is not None else []
        if model is not None:
            if not hasattr(model, 'classes_') or set(model.classes_) != {0, 1}:
                raise ValueError('The model must be fitted on both binary rating classes.')
            if not self.feature_columns:
                raise ValueError('Supply the model training columns.')
            self.positive_class_index = list(model.classes_).index(1)

    def score_events(self, events, profile, friends_going_map=None, avg_rating_map=None):
        """Return stable descending suggestions with capped favorite boosts and short reasons.

        :param events: eligible Event objects, normally already ordered by start time
        :param profile: UserProfile
        :param friends_going_map: optional event-ID to count mapping
        :param avg_rating_map: bundle-key to earlier user rating average, excluding future feedback
        :return: list of Suggestion objects, highest score first
        """
        events = list(events)
        if not events:
            return []
        friends_going_map, avg_rating_map = friends_going_map or {}, avg_rating_map or {}
        probabilities = self._probabilities(events, profile, friends_going_map, avg_rating_map)
        suggestions = []
        for index, event in enumerate(events):
            count = friends_going_map.get(event.event_id, 0)
            score = heuristic_score(event, profile, count)
            if probabilities is not None:
                score = min(1.0, float(probabilities[index]) + favorite_boost(event, profile))
            reasons = _reasons(event, profile, count, avg_rating_map.get(event.bundle_key))
            suggestions.append(models.Suggestion(event, score, reasons, count))
        # Course: A05 – stable sorting preserves the input order when scores tie.
        return sorted(suggestions, key=lambda suggestion: suggestion.score, reverse=True)

    def _probabilities(self, events, profile, friend_counts, averages):
        """Align candidate columns exactly to training before asking for positive probabilities."""
        if self.model is None:
            return None
        rows = []
        for event in events:
            rows.append(event_feature_row(event, profile, friend_counts.get(event.event_id, 0),
                                           averages.get(event.bundle_key, config.NEUTRAL_RATING)))
        matrix = to_feature_matrix(rows, self.feature_columns)
        return self.model.predict_proba(matrix)[:, self.positive_class_index]


def filter_suggestions(suggestions, profile, bundle_keys=(), favorites=False):
    """Apply OR semantics across selected bundles and favorites, preserving score order.

    :param suggestions: scored suggestions for one gap or Beyond your gaps
    :param profile: current favorite sets
    :param bundle_keys: selected bundle keys; empty means no bundle filter
    :param favorites: include events matching any favorite kind
    :return: all matching suggestions, or the original selection when no filter is active
    """
    bundle_keys = set(bundle_keys)
    if not favorites and not bundle_keys:
        return list(suggestions)
    result = []
    for suggestion in suggestions:
        event = suggestion.event
        if event.bundle_key in bundle_keys or (favorites and profile.favorite_kinds(event)):
            result.append(suggestion)
    return result


def make_label(rating):
    """Return one for a rating of at least four stars, rejecting invalid or absent ratings."""
    if type(rating) is not int or not config.RATING_MIN <= rating <= config.RATING_MAX:
        raise ValueError('A training label requires an integer rating from 1 to 5.')
    return int(rating >= config.LABEL_MIN_STARS)


def event_feature_row(event, profile, friends_going, earlier_avg_rating):
    """Create the explicit M4 feature dictionary without identifiers or private calendar data.

    :param event: public occurrence to encode
    :param profile: current focus and favorite sets
    :param friends_going: count of opted-in friends with this plan
    :param earlier_avg_rating: user's prior bundle average, or NEUTRAL_RATING
    :return: one row containing only the features listed in SPEC section 12.2
    """
    if type(friends_going) is not int or friends_going < 0:
        raise ValueError('Friends going must be a nonnegative integer.')
    if (not math.isfinite(earlier_avg_rating)
            or not config.RATING_MIN <= earlier_avg_rating <= config.RATING_MAX):
        raise ValueError('Earlier average must be between 1 and 5.')
    hour = event.start.hour
    period = 'evening'
    if hour < config.ML_MORNING_END_HOUR:
        period = 'morning'
    elif hour < config.ML_AFTERNOON_END_HOUR:
        period = 'afternoon'
    # SPEC 4.5: float is allowed for this ML feature only; money storage stays exact Decimal.
    price = float(event.price) if event.price is not None else 0.0
    return {'direction': event.direction_key, 'bundle': event.bundle_key, 'source': event.SOURCE,
            'location_type': event.location_type, 'time_of_day': period,
            'weekday': event.start.weekday(),
            'is_weekend': int(event.start.weekday() >= config.ML_WEEKEND_START),
            'start_hour': hour + event.start.minute / 60,
            'duration_minutes': event.duration_minutes(),
            'is_free': int(event.price is not None and event.price.is_zero()), 'price_chf': price,
            'members_only': int(event.members_only), 'is_recurring': int(event.is_recurring),
            'end_is_estimated': int(event.end_is_estimated),
            'wants_direction': int(profile.wants_direction(event)),
            'fav_series': int(event.series_id in profile.favorite_series_ids),
            'fav_club': int(event.club_id in profile.favorite_club_ids),
            'fav_bundle': int(event.bundle_key in profile.favorite_bundle_keys),
            'earlier_avg_rating_in_bundle': earlier_avg_rating, 'friends_going': friends_going}


def to_feature_matrix(rows, feature_columns=None):
    """One-hot encode categories and align unseen scoring values to the training schema.

    :param rows: feature dictionaries from event_feature_row
    :param feature_columns: training column order, or None while fitting
    :return: numeric pandas DataFrame suitable for scikit-learn
    """
    frame = pd.DataFrame(rows)
    if frame.empty:
        frame = pd.DataFrame(columns=config.ML_FEATURE_COLUMNS)
    elif not set(config.ML_FEATURE_COLUMNS).issubset(frame.columns):
        raise ValueError('Feature rows are missing required fields.')
    # Course: A08 – explicit columns also prevent accidental identifier/label leakage.
    frame = frame.loc[:, list(config.ML_FEATURE_COLUMNS)]
    matrix = pd.get_dummies(frame, columns=list(config.ML_CATEGORICAL_FEATURES), dtype=int)
    if feature_columns is not None:
        matrix = matrix.reindex(columns=feature_columns, fill_value=0)
    return matrix


def _training_context(connection, records):
    """Load each user's profile and privacy-filtered friend counts once per training build."""
    profiles, friend_counts = {}, {}
    event_ids = {row['event_id'] for row in records}
    for row in records:
        user_id = row['user_id']
        if user_id not in profiles:
            profiles[user_id] = database.get_user_profile(connection, user_id)
            friend_counts[user_id] = friends.friends_going_counts(connection, user_id, event_ids)
    return profiles, friend_counts


def _training_row(record, profile, friend_counts, history):
    """Encode one example using only previously accumulated bundle history."""
    event_row = record.copy()
    event_row['id'] = record['event_id']
    event = models.event_from_row(event_row)
    total, count = history.get((profile.user_id, event.bundle_key), (0, 0))
    earlier = total / count if count else config.NEUTRAL_RATING
    return event_feature_row(event, profile, friend_counts.get(event.event_id, 0), earlier)


def build_training_data(connection, now=None):
    """Build weighted examples without leaking a row's own rating or same-start peers.

    :param connection: open SQLite connection
    :param now: cutoff for available attended ratings
    :return: (feature DataFrame, binary label Series, sample-weight Series)
    """
    frame = database.get_training_interactions_df(connection, now)
    records = frame.reset_index().to_dict('records')
    profiles, friend_counts = _training_context(connection, records)
    rows, labels, weights, history = [], [], [], {}
    # Course: U03 s1 – add each timestamp batch to history only after every row was encoded.
    groups = itertools.groupby(records, key=lambda row: (row['user_id'], row['start_time']))
    for group_key, group in groups:
        batch = list(group)
        for record in batch:
            user_id = record['user_id']
            rows.append(_training_row(record, profiles[user_id], friend_counts[user_id], history))
            labels.append(make_label(record['rating']))
            own = not record['is_synthetic'] and not record['is_demo']
            weight = config.REAL_USER_SAMPLE_WEIGHT if own else config.SYNTHETIC_SAMPLE_WEIGHT
            weights.append(weight)
        for record in batch:
            key = record['user_id'], record['bundle_key']
            total, count = history.get(key, (0, 0))
            history[key] = total + record['rating'], count + 1
    return (to_feature_matrix(rows), pd.Series(labels, dtype=int, name='positive_rating'),
            pd.Series(weights, dtype=float, name='sample_weight'))


def train_production_model(X, y, weights):
    """Fit the specified seeded Random Forest, or return None for insufficient training data.

    :param X: encoded numeric feature DataFrame
    :param y: binary labels in the same row order
    :param weights: positive sample weights, with local genuine ratings weighted fivefold
    :return: fitted forest; None when fewer than fifty rows or only one label class exist
    """
    if len(X) != len(y) or len(y) != len(weights):
        raise ValueError('Features, labels and weights must have equal row counts.')
    if not set(y).issubset({0, 1}):
        raise ValueError('Model labels must be zero or one.')
    if any(not math.isfinite(weight) or weight <= 0 for weight in weights):
        raise ValueError('Training weights must be finite and positive.')
    if len(y) < config.MIN_TRAINING_ROWS or len(set(y)) < 2:
        return None
    # Course: L02, A10 – production learns from every eligible row; M6 handles held-out evaluation.
    model = RandomForestClassifier(n_estimators=config.RF_N_ESTIMATORS,
                                    max_depth=config.RF_MAX_DEPTH, random_state=config.RANDOM_SEED)
    model.fit(X, y, sample_weight=weights)
    return model


def _split_for_evaluation(X, y):
    """Return disjoint stratified train/validation/test rows with the course's fixed seed."""
    # Course: A11 – hold out 20%, then divide that set equally; neither step changes the seed.
    X_train, X_holdout, y_train, y_holdout = train_test_split(
        X, y, test_size=config.VAL_SHARE + config.TEST_SHARE,
        stratify=y, random_state=config.RANDOM_SEED)
    X_val, X_test, y_val, y_test = train_test_split(
        X_holdout, y_holdout, test_size=config.TEST_SHARE / (config.VAL_SHARE + config.TEST_SHARE),
        stratify=y_holdout, random_state=config.RANDOM_SEED)
    return X_train, X_val, X_test, y_train, y_val, y_test


def _comparison_models():
    """Create five new unweighted classifiers for each evaluation scaling variant."""
    return {
        'Random Forest': RandomForestClassifier(n_estimators=config.RF_N_ESTIMATORS,
                                               max_depth=config.RF_MAX_DEPTH,
                                               random_state=config.RANDOM_SEED),
        'Logistic Regression': LogisticRegression(max_iter=config.LOGISTIC_MAX_ITER,
                                                   random_state=config.RANDOM_SEED),
        'K-Nearest Neighbors': KNeighborsClassifier(n_neighbors=config.KNN_NEIGHBORS),
        'Decision Tree': DecisionTreeClassifier(random_state=config.RANDOM_SEED),
        'Gaussian Naive Bayes': GaussianNB(),
    }


def _classification_metrics(actual, predicted):
    """Return accuracy and macro precision/recall/F1, with undefined metrics set to zero."""
    # Course: A10 – macro averaging gives each label equal weight, even for unequal classes.
    precision, recall, f1, _ = precision_recall_fscore_support(
        actual, predicted, labels=[0, 1], average='macro', zero_division=0)
    return {'accuracy': float(accuracy_score(actual, predicted)),
            'precision': float(precision), 'recall': float(recall), 'f1': float(f1)}


def _evaluate_variants(train, val, y_train, y_val, scaled):
    """Fit one row per model and retain the forest for independent held-out reporting."""
    rows, forest = [], None
    for name, model in _comparison_models().items():
        model.fit(train, y_train)  # Comparison deliberately uses no production sample weights.
        metrics = _classification_metrics(y_val, model.predict(val))
        rows.append({'model': name, 'scaled': scaled,
                     'train_accuracy': float(accuracy_score(y_train, model.predict(train))),
                     'val_accuracy': metrics['accuracy'], 'val_precision': metrics['precision'],
                     'val_recall': metrics['recall'], 'val_f1': metrics['f1']})
        if name == 'Random Forest':
            forest = model
    return rows, forest


def evaluate_models(X, y):
    """Compare five classifiers twice and attach the unscaled forest's held-out test report.

    :param X: finite numeric feature DataFrame, without labels or identifiers
    :param y: binary label Series in the same row order; positive means at least four stars
    :return: ten-row comparison DataFrame with JSON-safe report metadata in .attrs;
             empty with an explanatory reason when stratified evaluation is not possible
    """
    if len(X) != len(y) or not set(y).issubset({0, 1}):
        raise ValueError('Evaluation requires equal feature/label counts and binary labels.')
    if not np.isfinite(X.to_numpy(dtype=float)).all():
        raise ValueError('Evaluation features must be finite numbers.')
    result = pd.DataFrame(columns=config.EVALUATION_COLUMNS)
    result.attrs = {'available': False, 'positive_share': float(y.mean()) if len(y) else 0.0,
                    'reason': 'Need at least 50 rated activities and enough of both labels.'}
    if len(y) < config.MIN_TRAINING_ROWS or len(set(y)) < 2:
        return result
    try:
        train, val, test, y_train, y_val, y_test = _split_for_evaluation(X, y)
    except ValueError:
        return result
    if any(len(set(labels)) < 2 for labels in (y_train, y_val, y_test)):
        return result
    rows, forest = _evaluate_variants(train, val, y_train, y_val, False)
    # Fit exactly once on training features; validation and test never influence the scaler.
    scaler = RobustScaler()
    scaler.fit(train)
    train_scaled, val_scaled = scaler.transform(train), scaler.transform(val)
    scaler.transform(test)  # Keep the course's third transform separate from every fit.
    scaled_rows, _ = _evaluate_variants(train_scaled, val_scaled, y_train, y_val, True)
    result = pd.DataFrame(rows + scaled_rows, columns=config.EVALUATION_COLUMNS)
    predictions = forest.predict(test)
    result.attrs = {
        'available': True, 'positive_share': float(y.mean()),
        'split_sizes': {'train': len(train), 'validation': len(val), 'test': len(test)},
        'test_metrics': _classification_metrics(y_test, predictions),
        'classification_report': classification_report(
            y_test, predictions, labels=[0, 1], target_names=['1–3 stars', '4–5 stars'],
            zero_division=0),
        'feature_importances': feature_importances(forest, X.columns).to_dict('records'),
    }
    return result


def feature_importances(model, feature_columns):
    """Return the fitted forest's feature importances in stable descending order."""
    if len(feature_columns) != len(model.feature_importances_):
        raise ValueError('Feature names must match the fitted model.')
    frame = pd.DataFrame({'feature': list(feature_columns),
                          'importance': model.feature_importances_})
    return frame.sort_values('importance', ascending=False, kind='stable').reset_index(drop=True)


def plot_model_comparison(results_df):
    """Return grouped validation-F1 bars for the unscaled and scaled classifiers."""
    # Course: A09 – pivot the comparison table so each model has two adjacent bars.
    values = results_df.pivot(index='model', columns='scaled', values='val_f1')
    values = values.reindex(results_df['model'].drop_duplicates())
    fig, axis = plt.subplots(figsize=config.CHART_SIZE, layout='constrained')
    width = config.CHART_BAR_WIDTH
    for scaled, offset, label, color in (
            (False, -width / 2, 'Unscaled', config.CHART_PRIMARY_COLOR),
            (True, width / 2, 'RobustScaler', config.CHART_SECONDARY_COLOR)):
        bars = axis.bar([i + offset for i in range(len(values))], values[scaled], width,
                        label=label, color=color)
        axis.bar_label(bars, fmt='%.2f', padding=config.CHART_LABEL_PADDING)
    axis.set_xticks(range(len(values)), [name.replace(' ', '\n') for name in values.index])
    axis.set_ylim(0, 1 + config.CHART_VALUE_MARGIN)
    axis.set_ylabel('Validation F1 (macro)')
    axis.set_title('Five classifiers, with and without scaling')
    axis.legend()
    plt.close(fig)
    return fig


def plot_feature_importances(importances_df):
    """Return the ten most influential forest features as a horizontal bar chart."""
    top = importances_df.sort_values('importance', ascending=False).head(
        config.FEATURE_IMPORTANCE_TOP_N)
    fig, axis = plt.subplots(figsize=config.CHART_SIZE, layout='constrained')
    bars = axis.barh(range(len(top)), top['importance'], color=config.CHART_PRIMARY_COLOR)
    labels = [textwrap.fill(name, config.CHART_LABEL_WIDTH) for name in top['feature']]
    axis.set_yticks(range(len(top)), labels)
    axis.invert_yaxis()
    axis.bar_label(bars, fmt='%.3f', padding=config.CHART_LABEL_PADDING)
    axis.margins(x=config.CHART_VALUE_MARGIN)
    axis.set_title('Random Forest: top feature importances')
    axis.set_xlabel('Relative importance (training split)')
    plt.close(fig)
    return fig
